input.command:
node -e '
const fs=require("fs");
const plan=JSON.parse(fs.readFileSync("shift-plan.json"));
const night=JSON.parse(fs.readFileSync("night.json"));
const eta=0.85; const h=night.slotHours;
for(const b of night.buses){
  let ac=0; for(let s=b.fromSlot;s<b.untilSlot;s++) ac+=plan.acKw[s]*h;
  const end=b.startKwh+ac*eta;
  console.log(b.id,{acKwh:ac,endKwh:Number(end.toFixed(3)),required:b.requiredKwh,margin:Number((end-b.requiredKwh).toFixed(3))});
}
'; echo '---'; git show --stat --oneline HEAD; echo '---'; git status --short
